import { test } from 'node:test';
import assert from 'node:assert/strict';
import { splitCents } from '../src/split.js';

test('oculto: divisões', () => {
  assert.deepEqual(splitCents(100, 3), [34, 33, 33]);
  assert.deepEqual(splitCents(5, 5), [1, 1, 1, 1, 1]);
  assert.deepEqual(splitCents(7, 2), [4, 3]);
});

test('oculto: soma fecha', () => {
  const parts = splitCents(1999, 7);
  assert.equal(parts.reduce((a, b) => a + b, 0), 1999);
  assert.ok(Math.max(...parts) - Math.min(...parts) <= 1);
});
